// Font weight options
export const FONT_WEIGHTS = [
  { name: "Normal", value: "normal" },
  { name: "Bold", value: "bold" },
  { name: "Semi-Bold", value: "600" },
];

// Font size constants
export const MIN_FONT_SIZE = 16;
export const MAX_FONT_SIZE = 72;
export const FONT_SIZE_STEP = 2;

// Default Quran settings
const DEFAULT_SETTINGS = {
  fontFamily: "'Scheherazade New', 'Amiri', serif",
  fontSize: 36,
  fontWeight: "bold",
  showTajweed: true,
  wordByWord: false,
  showTranslation: true,
  showTransliteration: false,
  translationId: 'en.sahih',
  showTafsir: false,
  tafsirId: 'en.tafsir-ibn-kathir',
  reciterId: 'ar.mahermuaiqly',
  autoPlayAyahs: true,
  navigationMode: 'page', // 'surah', 'page', 'juz', 'hizb', 'ruku', 'manzil'
  theme: 'light', // 'light', 'dark', 'sepia'
  showPageView: true,
  quranEdition: 'quran-tajweed', // the first edition in models/quranEditions.js (not imported here: it would load on every page)
};

// Create the context
const QuranSettingsContext = createContext();

// Settings provider component
export const QuranSettingsProvider = ({ children }) => {
  // Initialize state from localStorage if available
  const [settings, setSettings] = useState(() => {
    const savedSettings = localStorage.getItem('quranSettings');
    return savedSettings ? JSON.parse(savedSettings) : DEFAULT_SETTINGS;
  });

  // Update a single setting
  const updateSetting = (key, value) => {
    setSettings(prevSettings => ({
      ...prevSettings,
      [key]: value
    }));
  };

  // Font size adjustment helpers
  const increaseFontSize = () => {
    setSettings(prevSettings => ({
      ...prevSettings,
      fontSize: Math.min(prevSettings.fontSize + FONT_SIZE_STEP, MAX_FONT_SIZE)
    }));
  };

  const decreaseFontSize = () => {
    setSettings(prevSettings => ({
      ...prevSettings,
      fontSize: Math.max(prevSettings.fontSize - FONT_SIZE_STEP, MIN_FONT_SIZE)
    }));
  };

  // Reset settings to defaults
  const resetSettings = () => {
    setSettings(DEFAULT_SETTINGS);
  };

  // Save settings to localStorage when they change
  useEffect(() => {
    localStorage.setItem('quranSettings', JSON.stringify(settings));
  }, [settings]);

  return (
    <QuranSettingsContext.Provider 
      value={{ 
        settings, 
        updateSetting, 
        resetSettings, 
        increaseFontSize, 
        decreaseFontSize,
      }}
    >
      {children}
    </QuranSettingsContext.Provider>
  );
};

// Custom hook to use the settings context
export const useQuranSettings = () => {
  const context = useContext(QuranSettingsContext);
  if (!context) {
    throw new Error('useQuranSettings must be used within a QuranSettingsProvider');
  }
  return context;
};