// "Be the first to know": the newsletter sign-up band at the top of the footer, on every
// page. Emails go to prayer-times-api (newsletterStore); BillionMail sends later.
import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useLocation } from 'react-router-dom';
import { Box, Typography, InputBase, Button, Chip, Checkbox, FormControlLabel, Stack, alpha, useTheme } from '@mui/material';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import { subscribeToNewsletter } from '../../services/newsletterService';

const TOPICS = ['app', 'quran', 'ramadan', 'masjid'];
// Eight-point star (khatam) lattice, drawn once as a data URI.
const STAR = encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="56" height="56" viewBox="0 0 56 56"><g fill="none" stroke="#fff" stroke-opacity=".07"><rect x="16" y="16" width="24" height="24"/><rect x="16" y="16" width="24" height="24" transform="rotate(45 28 28)"/></g></svg>');

export default function NewsletterSignup() {
    const theme = useTheme();
    const { t, i18n } = useTranslation();
    const { pathname } = useLocation();
    const gold = theme.palette.secondary.main;
    const [email, setEmail] = useState('');
    const [topics, setTopics] = useState(['app']);
    const [consent, setConsent] = useState(false);
    const [trap, setTrap] = useState('');
    const [state, setState] = useState({ phase: 'idle', error: null });

    const toggle = (k) => setTopics((s) => (s.includes(k) ? s.filter((x) => x !== k) : [...s, k]));
    const submit = async (e) => {
        e.preventDefault();
        if (!consent) return setState({ phase: 'idle', error: t('newsletter.consent') });
        setState({ phase: 'sending', error: null });
        try {
            await subscribeToNewsletter(
                { email, consent, topics, website2: trap, source: pathname.slice(0, 80), locale: (i18n.language || 'en').slice(0, 2) },
                { rateMessage: t('newsletter.rate'), errorMessage: t('newsletter.error') },
            );
            setState({ phase: 'done', error: null });
        } catch (err) {
            setState({ phase: 'idle', error: err.message });
        }
    };

    return (
        <Box
            component="section"
            aria-labelledby="newsletter-title"
            sx={{
                position: 'relative', overflow: 'hidden', borderRadius: 4, mb: 6, p: { xs: 3, md: 5 },
                background: `radial-gradient(120% 140% at 100% 0%, ${alpha(gold, 0.22)} 0%, transparent 55%), url("data:image/svg+xml,${STAR}"), ${alpha('#000', 0.18)}`,
                border: `1px solid ${alpha(gold, 0.35)}`,
                boxShadow: `inset 0 1px 0 ${alpha('#fff', 0.08)}, 0 24px 60px -30px ${alpha('#000', 0.6)}`,
                backdropFilter: 'blur(6px)',
            }}
        >
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={{ xs: 3, md: 6 }} alignItems={{ md: 'center' }}>
                <Box sx={{ flex: 1, textAlign: 'start' }}>
                    <Typography variant="overline" sx={{ color: gold, letterSpacing: '0.22em', fontWeight: 600 }}>
                        {t('newsletter.eyebrow')}
                    </Typography>
                    <Typography id="newsletter-title" variant="h4" component="h2" sx={{ fontWeight: 700, lineHeight: 1.15, mt: 0.5, mb: 1.5, fontFamily: 'serif' }}>
                        {t('newsletter.title')}
                    </Typography>
                    <Typography variant="body2" sx={{ color: 'rgba(255,255,255,0.78)', maxWidth: 440 }}>
                        {t('newsletter.body')}
                    </Typography>
                </Box>

                <Box sx={{ flex: 1.15, minWidth: 0 }}>
                    {state.phase === 'done' ? (
                        <Stack direction="row" spacing={1.5} alignItems="center" role="status" sx={{ p: 2.5, borderRadius: 3, bgcolor: alpha(gold, 0.12), border: `1px solid ${alpha(gold, 0.4)}` }}>
                            <CheckCircleRoundedIcon sx={{ color: gold }} />
                            <Typography sx={{ fontWeight: 600 }}>{t('newsletter.done')}</Typography>
                        </Stack>
                    ) : (
                        <Box component="form" onSubmit={submit} noValidate>
                            <Stack direction="row" useFlexGap flexWrap="wrap" spacing={1} sx={{ mb: 2 }}>
                                {TOPICS.map((k) => {
                                    const on = topics.includes(k);
                                    return (
                                        <Chip
                                            key={k}
                                            label={t(`newsletter.topics.${k}`)}
                                            onClick={() => toggle(k)}
                                            aria-pressed={on}
                                            sx={{
                                                minHeight: 36, color: on ? theme.palette.primary.dark : 'rgba(255,255,255,0.85)', fontWeight: 600,
                                                bgcolor: on ? gold : 'transparent', border: `1px solid ${alpha(gold, on ? 1 : 0.45)}`,
                                                '&:hover': { bgcolor: on ? gold : alpha(gold, 0.12) },
                                            }}
                                        />
                                    );
                                })}
                            </Stack>
                            <Box sx={{ display: 'flex', gap: 1, p: 0.75, borderRadius: 999, bgcolor: alpha('#fff', 0.96), boxShadow: `0 0 0 4px ${alpha(gold, 0.15)}`, flexWrap: { xs: 'wrap', sm: 'nowrap' } }}>
                                <InputBase
                                    type="email"
                                    required
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    placeholder={t('newsletter.placeholder')}
                                    inputProps={{ 'aria-label': t('newsletter.placeholder'), autoComplete: 'email', maxLength: 120 }}
                                    sx={{ flex: 1, minWidth: 180, px: 2, color: theme.palette.primary.dark, fontSize: 16 }}
                                />
                                {/* Honeypot: hidden from people, filled by bots. */}
                                <input type="text" name="website2" value={trap} onChange={(e) => setTrap(e.target.value)} tabIndex={-1} autoComplete="off" aria-hidden="true" style={{ position: 'absolute', left: -9999, width: 1, height: 1 }} />
                                <Button
                                    type="submit"
                                    disabled={state.phase === 'sending'}
                                    sx={{
                                        borderRadius: 999, px: 3, minHeight: 48, fontWeight: 700, textTransform: 'none', width: { xs: '100%', sm: 'auto' },
                                        color: theme.palette.primary.dark,
                                        background: `linear-gradient(135deg, ${theme.palette.secondary.light}, ${gold})`,
                                        '&:hover': { background: `linear-gradient(135deg, ${gold}, ${theme.palette.secondary.dark})` },
                                    }}
                                >
                                    {state.phase === 'sending' ? t('newsletter.sending') : t('newsletter.button')}
                                </Button>
                            </Box>
                            <FormControlLabel
                                sx={{ mt: 1.5, alignItems: 'flex-start', '& .MuiTypography-root': { fontSize: 13, color: 'rgba(255,255,255,0.75)', pt: 1.1 } }}
                                control={<Checkbox checked={consent} onChange={(e) => setConsent(e.target.checked)} sx={{ color: alpha(gold, 0.7), '&.Mui-checked': { color: gold } }} />}
                                label={t('newsletter.consent')}
                            />
                            {state.error && (
                                <Typography role="alert" variant="body2" sx={{ color: '#ffb4a8', mt: 0.5 }}>{state.error}</Typography>
                            )}
                        </Box>
                    )}
                </Box>
            </Stack>
        </Box>
    );
}
