import apiConfig from '../config/apiConfig';

/**
 * The site's API client: the axios-style surface the services use (get/post/put/delete,
 * `{ params }`, resolves to `{ data, status }`, rejects with `error.response` /
 * `error.request`), on the browser's fetch. It replaced axios on 2026-11-07, which put
 * ~35 KB in the bundle every page loads.
 */
function url(path, params) {
    const u = new URL(`${apiConfig.baseUrl}${path}`, window.location.origin);
    if (params) {
        Object.entries(params).forEach(([k, v]) => {
            if (v !== undefined && v !== null) u.searchParams.set(k, v);
        });
    }
    return u.toString();
}

async function request(method, path, { params, data } = {}) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), apiConfig.timeout || 15000);
    let res;
    try {
        res = await fetch(url(path, params), {
            method,
            headers: { ...apiConfig.headers, ...(data !== undefined ? { 'Content-Type': 'application/json' } : {}) },
            body: data !== undefined ? JSON.stringify(data) : undefined,
            signal: controller.signal,
        });
    } catch (cause) {
        const error = new Error('No response received from the server. Please check your internet connection.');
        error.request = { method, path };
        error.cause = cause;
        throw error;
    } finally {
        clearTimeout(timer);
    }
    const text = await res.text();
    let body = text;
    try { body = text ? JSON.parse(text) : null; } catch (e) { /* not JSON: keep the text */ }
    if (!res.ok) {
        const error = new Error(body?.message || body?.error || `Error ${res.status}: ${res.statusText}`);
        error.response = { status: res.status, statusText: res.statusText, data: body };
        throw error;
    }
    return { data: body, status: res.status, headers: res.headers };
}

const api = {
    get: (path, config) => request('GET', path, config),
    delete: (path, config) => request('DELETE', path, config),
    post: (path, data, config) => request('POST', path, { ...config, data }),
    put: (path, data, config) => request('PUT', path, { ...config, data }),
};

export default api;
